sys_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
    var table = g_form.getValue('table');
    var document = g_form.getValue('document');

    if ((table == 'x_hsb11_mss_c_proc_mss_custody_trade' || table == 'x_hsb11_mss_c_proc_mss_custody_case' || table == 'x_hsb11_mss_c_proc_mss_custody_task') && g_form.getValue('message') == 'You have been mentioned' && (g_form.getValue('field_name') == 'comments' || g_form.getValue('field_name') == 'work_notes')) {
        var url = '/x/hsb11/mss-custody-workspace/record/' + table + '/' + document;
        top.window.location = url;
    }

}
